package com.scms.backend.scheduling; import java.util.UUID; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/coach/class-sessions/{sessionId}/attendance") class AttendanceController{final AttendanceService service;AttendanceController(AttendanceService s){service=s;}@GetMapping ResponseEntity<?> list(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID sessionId){return ResponseEntity.ok(service.list(UUID.fromString(jwt.getSubject()),sessionId));}@PatchMapping("/{attendanceId}") ResponseEntity<?> update(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID sessionId,@PathVariable UUID attendanceId,@RequestBody AttendanceUpdateRequest req){return ResponseEntity.ok(service.update(UUID.fromString(jwt.getSubject()),sessionId,attendanceId,req));}}
